import{_ as o,a0 as s,w as l,s as d,ao as u,I as n,x as t,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"如何在Ubuntu 14.04 LTS上安裝MariaDB | LCTT x X-CMD","titleTemplate":false,"description":"如何在Ubuntu 14.04 LTS上安裝MariaDB | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Ubuntu 14.04 LTS上安裝MariaDB | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Ubuntu 14.04 LTS上安裝MariaDB | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141029 How to Install MariaDB in Ubuntu 14.04 LTS","title":"如何在Ubuntu 14.04 LTS上安裝MariaDB","tag":"201411","desc":""},"relativePath":"201411/20141029 How to Install MariaDB in Ubuntu 14.04 LTS.md","filePath":"[post].md"}'),p={name:"201411/20141029 How to Install MariaDB in Ubuntu 14.04 LTS.md"};function m(b,a,M,h,D,T){const r=s("Link");return l(),d("div",null,[a[13]||(a[13]=u(`<h1 id="如何在ubuntu-14-04-lts上安裝mariadb" tabindex="-1">如何在Ubuntu 14.04 LTS上安裝MariaDB <a class="header-anchor" href="#如何在ubuntu-14-04-lts上安裝mariadb" aria-label="Permalink to “如何在Ubuntu 14.04 LTS上安裝MariaDB”">​</a></h1><p>MariaDB是一個開源資料庫且100%與MySQL兼容，目標是替代MySQL資料庫。</p><h3 id="mariadb的背景" tabindex="-1">MariaDB的背景 : <a class="header-anchor" href="#mariadb的背景" aria-label="Permalink to “MariaDB的背景 :”">​</a></h3><p>2008年，MySQL被後來被Oracle在2010年收購的<strong>Sun Microsystems</strong>收購了。 最初被Sun公司的收購由於符合項目的需要而受到MySQL社區的歡呼，但是這種情緒並沒有持續太久，接下來被Oracle的收購，不幸期望遠遠低於預期。許多MySql的開發者離開了Sun和Oracle公司開始新的項目。在他們中間就有MySQL的創建者以及項目長期技術帶頭人之一的<strong>Michael ‘Monty’ Widenius</strong>。Monty和他的團隊創建了MySQL的一個fork版本並且命名它為<strong>MariaDB</strong>。</p><p>本篇我們會討論如何在Ubuntu上安裝MariaDB。默認上MariaDB的包並沒有在Ubuntu倉庫中。要安裝MariaDB，我們首先要設置MariaDB倉庫。</p><h4 id="設置-mariadb-倉庫" tabindex="-1">設置 MariaDB 倉庫 <a class="header-anchor" href="#設置-mariadb-倉庫" aria-label="Permalink to “設置 MariaDB 倉庫”">​</a></h4><pre><code>$ sudo apt-get install software-properties-common
$ sudo apt-key adv --recv-keys --keyserver hkp://keyserver.ubuntu.com:80 0xcbcb082a1bb943db
$ sudo add-apt-repository &#39;deb http://sfo1.mirrors.digitalocean.com/mariadb/repo/10.0/ubuntu trusty main&#39;
</code></pre><h4 id="安裝-mariadb" tabindex="-1">安裝 MariaDB : <a class="header-anchor" href="#安裝-mariadb" aria-label="Permalink to “安裝 MariaDB :”">​</a></h4><pre><code>$ sudo apt-get update
$ sudo apt-get install mariadb-server
</code></pre><p>在安裝中，你會被要求設置MariaDB的root密碼。</p><p><img src="http://www.linuxtechi.com/wp-content/uploads/2014/10/mariadb-root-1024x442-1.jpg" alt=""></p><h4 id="從命令列連接到mariadb" tabindex="-1">從命令列連接到MariaDB : <a class="header-anchor" href="#從命令列連接到mariadb" aria-label="Permalink to “從命令列連接到MariaDB :”">​</a></h4><pre><code>linuxtechi@mail:~$ mysql -uroot -p
Enter password: 
Welcome to the MariaDB monitor.  Commands end with ; or \\g.
Your MariaDB connection id is 40
Server version: 10.0.14-MariaDB-1~trusty-log mariadb.org binary distribution
Copyright (c) 2000, 2014, Oracle, SkySQL Ab and others.
Type &#39;help;&#39; or &#39;\\h&#39; for help. Type &#39;\\c&#39; to clear the current input statement.
MariaDB [(none)]&gt;
</code></pre><h4 id="maria-db-服務" tabindex="-1">Maria DB 服務 <a class="header-anchor" href="#maria-db-服務" aria-label="Permalink to “Maria DB 服務”">​</a></h4><pre><code>$ sudo /etc/init.d/mysql stop
$ sudo /etc/init.d/mysql start
</code></pre><hr>`,16)),n("p",null,[a[1]||(a[1]=t("via: ",-1)),e(r,{href:"http://www.linuxtechi.com/install-mariadb-in-ubuntu/"},{default:i(()=>[...a[0]||(a[0]=[t("http://www.linuxtechi.com/install-mariadb-in-ubuntu/",-1)])]),_:1})]),n("p",null,[a[5]||(a[5]=t("作者：",-1)),e(r,{href:"http://www.linuxtechi.com/author/pradeep/"},{default:i(()=>[...a[2]||(a[2]=[t("Pradeep Kumar",-1)])]),_:1}),a[6]||(a[6]=t(" 譯者：",-1)),e(r,{href:"https://github.com/geekpi"},{default:i(()=>[...a[3]||(a[3]=[t("geekpi",-1)])]),_:1}),a[7]||(a[7]=t(" 校對：",-1)),e(r,{href:"https://github.com/wxy"},{default:i(()=>[...a[4]||(a[4]=[t("wxy",-1)])]),_:1})]),n("p",null,[a[10]||(a[10]=t("本文由 ",-1)),e(r,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[8]||(a[8]=[t("LCTT",-1)])]),_:1}),a[11]||(a[11]=t(" 原創翻譯，",-1)),e(r,{href:"http://linux.cn/"},{default:i(()=>[...a[9]||(a[9]=[t("Linux中國",-1)])]),_:1}),a[12]||(a[12]=t(" 榮譽推出",-1))])])}const c=o(p,[["render",m]]);export{S as __pageData,c as default};
